const items = $input.all();
const currentYear = new Date().getFullYear();

const groupedByDate = {};
const result = [];

// month mapping
const monthNames = [
  "Jan","Feb","Mar","Apr","May","Jun",
  "Jul","Aug","Sep","Oct","Nov","Dec"
];

// Step 1 — group records
for (const item of items) {
  const date = item.json.Date; // MM-DD
  const dateWithYear = `${date}-${currentYear}`;

  if (!groupedByDate[dateWithYear]) {
    groupedByDate[dateWithYear] = {
      descriptions: [],
      base: item.json
    };
  }

  groupedByDate[dateWithYear].descriptions.push(
    item.json["Task Description"]
  );
}

// detect month
const firstDate = items[0].json.Date;
const month = parseInt(firstDate.split('-')[0], 10) - 1;

const start = new Date(currentYear, month, 1);
const end = new Date(currentYear, month + 1, 0);

// Step 2 — build full month
for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {

  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  const key = `${mm}-${dd}-${currentYear}`;

  const monthName = monthNames[d.getMonth()];
  const day = d.getDay();
  const isWeekend = (day === 0 || day === 6);

  if (groupedByDate[key]) {

    const base = groupedByDate[key].base;
    const comment = isWeekend ? "Weekend" : (base.Comments || "");

    result.push({
      json: {
        ...base,
        Month: monthName,
        Date: key,
        "Task Start Date": key,
        "Task End Date": key,
        "Task Description": (isWeekend || comment === "Holiday/Leave")
          ? ""
          : groupedByDate[key].descriptions.join('\n'),
        Comments: comment
      }
    });

  } else {

    const comment = isWeekend ? "Weekend" : "Holiday/Leave";

    result.push({
      json: {
        Month: monthName,
        Date: key,
        "Task Start Date": key,
        "Task End Date": key,
        Environment: "Boomi",
        AdminDevSupport: "Support",
        "Task Description": "",
        Complexity: "",
        "Actual Efforts(hrs)": "8",
        Status: "",
        Comments: comment
      }
    });

  }
}

return result;

// ===== USER INPUT =====
const month = $input.first().json.headers.month;      // 1 = Jan
const year = $input.first().json.headers.year;

// optional holidays (format: MM-DD)
// leave [] empty if no holidays
const holidays = $input.first().json.headers.holidays; 
// ======================

const days = new Date(year, month, 0).getDate();
const binaryData = items[0].binary;

const output = [];

for (let d = 1; d <= days; d++) {

  const date = new Date(year, month - 1, d);
  const dayOfWeek = date.getDay(); // 0=Sun, 6=Sat

  const sheetName =
    `${String(month).padStart(2,'0')}-${String(d).padStart(2,'0')}`;

  const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);
  const isHoliday = holidays.includes(sheetName);

  // skip weekends + holidays
  if (isWeekend || isHoliday) continue;

  output.push({
    json: { sheetName },
    binary: binaryData
  });
}

return output;
